  <title>Computer Languages Quiz</title>
  <style>
    :root {
      color-scheme: light;
      --bg: #f4f7fb;
      --surface: #ffffff;
      --surface-2: #f8fafc;
      --text: #102033;
      --muted: #5f6b7a;
      --border: #d8e0ea;
      --accent: #2563eb;
      --accent-weak: #e8f0ff;
      --shadow: 0 18px 50px rgba(16, 32, 51, 0.12);
      --radius: 20px;
    }

    * {
      box-sizing: border-box;
    }

    body {
      margin: 0;
      font-family: Inter, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      background:
        radial-gradient(circle at top, rgba(37, 99, 235, 0.14), transparent 35%),
        var(--bg);
      color: var(--text);
      min-height: 100vh;
      line-height: 1.5;
    }

    .page {
      width: min(920px, calc(100% - 32px));
      margin: 40px auto;
    }

    .hero {
      background: linear-gradient(135deg, #ffffff, #f4f8ff);
      border: 1px solid rgba(216, 224, 234, 0.8);
      box-shadow: var(--shadow);
      border-radius: 28px;
      padding: 32px;
      margin-bottom: 24px;
    }

    .eyebrow {
      margin: 0 0 10px;
      color: var(--accent);
      font-weight: 700;
      letter-spacing: 0.08em;
      text-transform: uppercase;
      font-size: 0.78rem;
    }

    h1 {
      margin: 0;
      font-size: clamp(2rem, 3vw, 3rem);
      line-height: 1.1;
    }

    .subtitle {
      margin: 12px 0 0;
      color: var(--muted);
      max-width: 60ch;
    }

    form {
      display: grid;
      gap: 20px;
    }

    .form-field {
      background: var(--surface);
      border: 1px solid var(--border);
      border-radius: var(--radius);
      padding: 24px;
      box-shadow: 0 8px 30px rgba(16, 32, 51, 0.06);
    }

    .question-head {
      display: grid;
      gap: 8px;
      margin-bottom: 18px;
    }

    .question-title {
      font-size: 1.15rem;
      font-weight: 700;
      margin: 0;
    }

    .help-text {
      margin: 0;
      color: var(--muted);
      font-size: 0.96rem;
    }

    .choices {
      display: grid;
      gap: 12px;
    }

    .choice {
      display: flex;
      align-items: flex-start;
      gap: 12px;
      padding: 14px 16px;
      border-radius: 16px;
      border: 1px solid var(--border);
      background: var(--surface-2);
      transition: border-color 0.15s ease, background-color 0.15s ease, transform 0.15s ease;
      cursor: pointer;
    }

    .choice:hover,
    .choice:focus-within {
      border-color: rgba(37, 99, 235, 0.45);
      background: var(--accent-weak);
      transform: translateY(-1px);
    }

    .choice input {
      margin-top: 3px;
      width: 18px;
      height: 18px;
      accent-color: var(--accent);
      flex: 0 0 auto;
    }

    .choice span {
      display: block;
    }

    .choice strong {
      display: block;
      margin-bottom: 2px;
    }

    .actions {
      display: flex;
      justify-content: flex-end;
      padding-top: 4px;
    }

    button {
      appearance: none;
      border: 0;
      border-radius: 999px;
      padding: 14px 22px;
      font: inherit;
      font-weight: 700;
      color: white;
      background: linear-gradient(135deg, #2563eb, #1d4ed8);
      box-shadow: 0 12px 24px rgba(37, 99, 235, 0.25);
      cursor: pointer;
    }

    button:hover {
      filter: brightness(1.02);
    }

    .result {
      margin: 0;
      min-height: 1.5em;
      color: var(--muted);
      font-weight: 600;
    }

    @media (max-width: 640px) {
      .page {
        width: min(100% - 20px, 920px);
        margin: 20px auto;
      }

      .hero,
      .form-field {
        padding: 20px;
      }

      .actions {
        justify-content: stretch;
      }

      button {
        width: 100%;
      }
    }
  </style>
</head>
<body>
  <main class="page">
    <section class="hero" aria-labelledby="quiz-title">
      <p class="eyebrow">Knowledge check</p>
      <h1 id="quiz-title">Computer Languages Quiz</h1>
      <p class="subtitle">Select any answers that apply for each question. This quiz uses checkboxes so you can choose multiple options per question.</p>
    </section>

    <form id="quiz-form">
      <div class="form-field">
        <div class="question-head">
          <p class="question-title">1. Which of these are programming languages?</p>
          <p class="help-text">Choose all that are commonly used to write software.</p>
        </div>
        <div class="choices">
          <label class="choice"><input type="checkbox" name="q1" value="python"><span><strong>Python</strong>Popular for scripting, automation, and data work.</span></label>
          <label class="choice"><input type="checkbox" name="q1" value="javascript"><span><strong>JavaScript</strong>Runs in browsers and many server-side tools.</span></label>
          <label class="choice"><input type="checkbox" name="q1" value="html"><span><strong>HTML</strong>Used to structure web pages, not a programming language.</span></label>
          <label class="choice"><input type="checkbox" name="q1" value="ruby"><span><strong>Ruby</strong>A general-purpose language with elegant syntax.</span></label>
        </div>
      </div>

      <div class="form-field">
        <div class="question-head">
          <p class="question-title">2. Which languages are commonly used for web development?</p>
        </div>
        <div class="choices">
          <label class="choice"><input type="checkbox" name="q2" value="javascript"><span><strong>JavaScript</strong>Adds interactivity to web apps.</span></label>
          <label class="choice"><input type="checkbox" name="q2" value="css"><span><strong>CSS</strong>Styles the look of web interfaces.</span></label>
          <label class="choice"><input type="checkbox" name="q2" value="go"><span><strong>Go</strong>Often used for backend services and tooling.</span></label>
          <label class="choice"><input type="checkbox" name="q2" value="sql"><span><strong>SQL</strong>Queries data stored in databases.</span></label>
        </div>
      </div>

      <div class="form-field">
        <div class="question-head">
          <p class="question-title">3. Which of these are compiled programming languages?</p>
        </div>
        <div class="choices">
          <label class="choice"><input type="checkbox" name="q3" value="c"><span><strong>C</strong>A classic compiled language used in systems programming.</span></label>
          <label class="choice"><input type="checkbox" name="q3" value="rust"><span><strong>Rust</strong>Designed for performance and memory safety.</span></label>
          <label class="choice"><input type="checkbox" name="q3" value="python"><span><strong>Python</strong>Typically interpreted at runtime.</span></label>
          <label class="choice"><input type="checkbox" name="q3" value="java"><span><strong>Java</strong>Compiled to bytecode for the JVM.</span></label>
        </div>
      </div>

      <div class="actions">
        <button type="submit">Submit quiz</button>
      </div>
      <p class="result" id="result" aria-live="polite"></p>
    </form>
  </main>

  <script>
    const quizForm = document.getElementById('quiz-form');
    const result = document.getElementById('result');

    quizForm.addEventListener('submit', (event) => {
      event.preventDefault();
      result.textContent = 'Quiz submitted. Thanks for participating!';
    });
  </script>
</body>
</html>
